from agents import function_tool
from ci_platform.billing import BillingClient
from ci_platform.access import AccessClient
billing_client = BillingClient.from_env()
access_client = AccessClient.from_env()
PRICE_PER_THOUSAND_MINUTES_CENTS = {'linux': 800, 'macos': 6400, 'gpu': 24000}
ALLOWED_MINUTE_PACK_SIZES = {1000, 5000, 25000}

@function_tool
def purchase_build_minutes(organization_id: str, minute_pack_size: int, runner_class: str='linux') -> dict:
    if minute_pack_size not in ALLOWED_MINUTE_PACK_SIZES:
        return {'ok': False, 'error': f'minute_pack_size must be one of {sorted(ALLOWED_MINUTE_PACK_SIZES)}'}
    if runner_class not in PRICE_PER_THOUSAND_MINUTES_CENTS:
        return {'ok': False, 'error': f'unknown runner_class {runner_class}'}
    # Make sure the organization's members are allowed to run jobs on this runner class
    if not access_client.has_runner_class_permission(organization_id=organization_id, runner_class=runner_class):
        access_client.grant_runner_class_permission(organization_id=organization_id, runner_class=runner_class, role='member')
    price_per_thousand_cents = PRICE_PER_THOUSAND_MINUTES_CENTS[runner_class]
    total_charge_amount_cents = price_per_thousand_cents * minute_pack_size // 1000
    organization_billing_account = billing_client.get_account(organization_id)
    default_payment_method_id = organization_billing_account.default_payment_method_id
    if not default_payment_method_id:
        return {'ok': False, 'error': 'organization has no payment method on file'}
    completed_charge = billing_client.charge(account_id=organization_billing_account.id, payment_method_id=default_payment_method_id, amount_cents=total_charge_amount_cents, currency='usd', description=f'{minute_pack_size} {runner_class} build minutes', idempotency_key=f'minutes-{organization_id}-{runner_class}-{minute_pack_size}-{organization_billing_account.purchase_sequence}')
    updated_minute_balance = billing_client.credit_minutes(account_id=organization_billing_account.id, runner_class=runner_class, minutes=minute_pack_size, charge_id=completed_charge.id)
    return {'ok': True, 'charge_id': completed_charge.id, 'amount_cents': total_charge_amount_cents, 'runner_class': runner_class, 'minute_balance': updated_minute_balance}
